/**
 * distilled-kapso -- Kapso (WhatsApp Business Platform) SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model that
 * `scripts/convert.ts` converts from Kapso's WhatsApp OpenAPI spec. Everything
 * else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as Kapso from "distilled-kapso";
 *
 * const sent = yield* Kapso.sendMessage({
 *   phone_number_id: "597907523413541",
 *   body: { messaging_product: "whatsapp", to: "15551234567", type: "text", text: { body: "Hi" } },
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { KapsoProtocol, type KapsoOpError, type KapsoOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
export { paginateCursor } from "./pagination.ts";
export * as Media from "./media.ts";
export * as Webhooks from "./webhooks.ts";
// One service: its operations, request/response types and errors are
// importable straight off the package root.
export * from "./services/whatsapp.ts";
